	@Test
	void bindingAssignmentTransitionsRetainFrameOwnershipWithoutRdfEquality() {
		assertOptionalTransitionOwnership(true);
	}

	private void assertOptionalTransitionOwnership(boolean bindingAssignment) {
		LeftJoin expression = new LeftJoin(new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o")),
				new StatementPattern(Var.of("s"), Var.of("q"), Var.of("optional")));
		ProbeValue value = new ProbeValue("same-value");
		QueryAlgebraBindingAnalysis analysis = bindingAssignment
				? QueryAlgebraBindingAnalysis.forBindingAssignment(expression, bindings(value))
				: QueryAlgebraBindingAnalysis.withBindingValues(expression, bindings(value));
		var firstInput = analysis.rootContext();
		var firstLeft = analysis.childInput(expression, expression.getLeftArg(), firstInput);
		var firstRight = analysis.childInput(expression, expression.getRightArg(), firstInput);
		assertThat(analysis.childInput(expression, expression.getLeftArg(), firstInput)).isSameAs(firstLeft);
		assertThat(analysis.childInput(expression, expression.getRightArg(), firstInput)).isSameAs(firstRight);
		assertThat(firstLeft.externalValues().get("input")).isSameAs(value);
		assertThat(firstRight.externalValues().get("input")).isSameAs(value);

		ProbeValue distinctValue = new ProbeValue("same-value");
		var distinctInput = QueryAlgebraBindingAnalysis.withBindingValues(expression, bindings(distinctValue))
				.rootContext();
		var distinctLeft = analysis.childInput(expression, expression.getLeftArg(), distinctInput);
		var distinctRight = analysis.childInput(expression, expression.getRightArg(), distinctInput);
		assertThat(distinctLeft).isNotSameAs(firstLeft);
		assertThat(distinctRight).isNotSameAs(firstRight);
		assertThat(distinctLeft.externalValues().get("input")).isSameAs(distinctValue);
		assertThat(distinctRight.externalValues().get("input")).isSameAs(distinctValue);
		assertThat(value.hashCalls).hasValue(0);
		assertThat(value.equalsCalls).hasValue(0);
		assertThat(distinctValue.hashCalls).hasValue(0);
		assertThat(distinctValue.equalsCalls).hasValue(0);
	}

	private static final class CountingStatementPattern extends StatementPattern {
		private static final long serialVersionUID = 1L;
		private final AtomicInteger bindingReads;

		private CountingStatementPattern(String predicate, String object, AtomicInteger bindingReads) {
			super(Var.of("s"), Var.of(predicate), Var.of(object));
			this.bindingReads = bindingReads;
		}

		@Override
		public Set<String> getBindingNames() {
			bindingReads.incrementAndGet();
			return super.getBindingNames();
		}
	}

	private static MapBindingSet bindings(Value value) {
		MapBindingSet bindings = new MapBindingSet();
		bindings.addBinding("input", value);
		return bindings;
	}

	private static final class ProbeValue implements Value {
		private static final long serialVersionUID = 1L;
		private final String value;
		private final AtomicInteger hashCalls = new AtomicInteger();
		private final AtomicInteger equalsCalls = new AtomicInteger();

		private ProbeValue(String value) {
			this.value = value;
		}

		@Override
		public String stringValue() {
			return value;
		}

		@Override
		public boolean equals(Object other) {
			equalsCalls.incrementAndGet();
			return other instanceof ProbeValue probe && value.equals(probe.value);
		}

		@Override
		public int hashCode() {
			hashCalls.incrementAndGet();
			return value.hashCode();
		}
	}
